"""Malayalam birth-star and Lagna readings, matching the English and Tamil ones in life.py."""

NAKSHATRA_ML = {
    'Ashwini': 'അശ്വതി നക്ഷത്രത്തിൽ ജനിച്ച നിങ്ങൾ ചുറുചുറുക്കും മൂർച്ചയുള്ള ബുദ്ധിയും തളരാത്ത ധൈര്യവും ഉള്ളവരാണ്. കുതിരമുഖം എന്ന പ്രതീകം പോലെ ഏതു കാര്യത്തിലും വേഗത കാണിച്ച് മുന്നിലെത്തും. വൈദ്യം, ഭരണം, പുതിയ സംരംഭങ്ങൾ എന്നിവയിൽ ശോഭിക്കും. സ്വാതന്ത്ര്യബോധവും സഹായമനസ്സുമുണ്ട്. തിടുക്കത്തിലുള്ള തീരുമാനങ്ങൾ ഒഴിവാക്കിയാൽ വലിയ വിജയം നേടാം.',
    'Bharani': 'ഭരണി നക്ഷത്രത്തിൽ ജനിച്ച നിങ്ങൾ ഉറച്ച മനോബലവും കഠിനാധ്വാനവും ആകർഷകമായ വ്യക്തിത്വവും ഉള്ളവരാണ്. എത്ര പ്രയാസമുള്ള സാഹചര്യത്തെയും നേരിടാനുള്ള ധൈര്യമുണ്ട്. കലാഭിരുചിയും സത്യസന്ധതയും ആസ്വാദനശേഷിയും ഉണ്ട്. പിടിവാശി കുറച്ച് സമചിത്തത പാലിച്ചാൽ ജീവിതത്തിൽ ഉയർന്ന നിലയിലെത്തും.',
    'Krittika': 'കാർത്തിക നക്ഷത്രത്തിൽ ജനിച്ച നിങ്ങൾക്ക് സൂര്യന്റെ സ്വാധീനത്താൽ ഗാംഭീര്യവും നേതൃശേഷിയും മൂർച്ചയുള്ള ബുദ്ധിയും ലഭിച്ചിരിക്കുന്നു. അഗ്നി പോലെ ജ്വലിക്കുന്ന ദൃഢനിശ്ചയമുണ്ട്. ധർമ്മബോധവും സത്യസന്ധതയുമാണ് നിങ്ങളുടെ ശക്തി. മുൻകോപം നിയന്ത്രിച്ചാൽ സമൂഹത്തിൽ വലിയ സ്വാധീനം നേടും.',
    'Rohini': 'രോഹിണി നക്ഷത്രത്തിൽ ജനിച്ച നിങ്ങൾ ആകർഷകമായ രൂപവും മധുരമായ സംസാരവും ആസ്വാദനബോധവും ഉള്ളവരാണ്. ചന്ദ്രന്റെ അനുഗ്രഹത്താൽ കല, വ്യാപാരം, പൊതുബന്ധങ്ങൾ എന്നിവയിൽ വലിയ വിജയം നേടും. ധനം, വാഹനസുഖം, കുടുംബസന്തോഷം എന്നിവ സ്വാഭാവികമായി ലഭിക്കും. വികാരാധീനത നിയന്ത്രിക്കുന്നത് നല്ലത്.',
    'Mrigashira': 'മകയിരം നക്ഷത്രത്തിൽ ജനിച്ച നിങ്ങൾ അറിവുതേടലും സമർത്ഥമായ സംസാരവും സൗമ്യസ്വഭാവവും ഉള്ളവരാണ്. മാനിനെപ്പോലെ ചുറുചുറുക്കും ജാഗ്രതയുമുണ്ട്. ഗവേഷണം, എഴുത്ത്, ആശയവിനിമയ മേഖലകളിൽ തിളങ്ങും. സംശയസ്വഭാവം ഒഴിവാക്കി ഉറച്ച തീരുമാനങ്ങളെടുക്കുന്നത് നന്ന്.',
    'Ardra': 'തിരുവാതിര നക്ഷത്രത്തിൽ ജനിച്ച നിങ്ങൾ തീവ്രമായ ചിന്തയും മൂർച്ചയുള്ള വിശകലനശേഷിയും എന്തിനെയും ആഴത്തിൽ മനസ്സിലാക്കാനുള്ള കഴിവും ഉള്ളവരാണ്. രുദ്രാംശത്താൽ പരീക്ഷണങ്ങൾ കടന്ന് നേട്ടങ്ങൾ കൈവരിക്കും. ആധുനിക ശാസ്ത്രം, സാങ്കേതികവിദ്യ, ഗവേഷണം എന്നിവയിൽ ഉന്നതിയിലെത്തും.',
    'Punarvasu': 'പുണർതം നക്ഷത്രത്തിൽ ജനിച്ച നിങ്ങൾ ശാന്തസ്വഭാവവും ധർമ്മചിന്തയും നല്ല ഗുണങ്ങളും ഉള്ളവരാണ്. നഷ്ടപ്പെട്ടത് വീണ്ടെടുക്കാനുള്ള അപൂർവ്വ ഭാഗ്യമുണ്ട്. വ്യാഴത്തിന്റെ അനുഗ്രഹത്താൽ വിദ്യ, ആത്മീയത, അധ്യാപനം, ഉപദേശം എന്നിവയിൽ വലിയ പ്രശസ്തി നേടും.',
    'Pushya': 'പൂയം നക്ഷത്രത്തിൽ ജനിച്ച നിങ്ങൾ ത്യാഗമനോഭാവവും സത്യസന്ധതയും ഭക്തിയും ഉള്ളവരാണ്. എല്ലാ നക്ഷത്രങ്ങളിലും ഏറ്റവും ശ്രേഷ്ഠമായ ശുഭനക്ഷത്രമാണിത്. അധ്വാനത്താൽ പടിപടിയായി മുന്നേറി സ്ഥിരമായ സമ്പത്തും ജനങ്ങളുടെ ആദരവും നേടും.',
    'Ashlesha': 'ആയില്യം നക്ഷത്രത്തിൽ ജനിച്ച നിങ്ങൾ ബുദ്ധികൂർമ്മതയും നയതന്ത്രപരമായ സംസാരവും കാര്യങ്ങൾ മുൻകൂട്ടി അറിയാനുള്ള ഉൾക്കാഴ്ചയും ഉള്ളവരാണ്. സർപ്പപ്രതീകം പോലെ സന്ദർഭോചിത ബുദ്ധിയാൽ ഏതു വെല്ലുവിളിയും ജയിക്കും. വ്യാപാരം, സാമ്പത്തികം, രാഷ്ട്രീയം എന്നിവയിൽ സ്വാധീനം നേടും.',
    'Magha': 'മകം നക്ഷത്രത്തിൽ ജനിച്ച നിങ്ങൾ ഗാംഭീര്യമുള്ള രൂപവും ഭരണശേഷിയും പിതൃക്കളുടെ അനുഗ്രഹവും ഉള്ളവരാണ്. സിംഹാസന പ്രതീകം പോലെ നേതൃസ്ഥാനങ്ങൾ വഹിക്കും. ഉദാരമനസ്സും മാന്യമായ ജീവിതവും ലഭിക്കും.',
    'Purva Phalguni': 'പൂരം നക്ഷത്രത്തിൽ ജനിച്ച നിങ്ങൾ പ്രസന്നമുഖവും കലാഭിരുചിയും ആകർഷകമായ സംസാരവും ഉള്ളവരാണ്. ശുക്രന്റെ അനുഗ്രഹത്താൽ സുഖജീവിതം, സുഹൃത്തുക്കളുടെ പിന്തുണ, സന്തുഷ്ട കുടുംബം എന്നിവ ലഭിക്കും. ആഡംബരച്ചെലവുകൾ കുറച്ചാൽ സമ്പാദ്യം വർധിക്കും.',
    'Uttara Phalguni': 'ഉത്രം നക്ഷത്രത്തിൽ ജനിച്ച നിങ്ങൾ നൽകിയ വാക്ക് പാലിക്കുന്ന ഉത്തമ സ്വഭാവമുള്ളവരാണ്. സൂര്യന്റെ സ്വാധീനത്താൽ നേതൃഗുണവും സൽപ്പേരുമുണ്ട്. സർക്കാർ അനുകൂല്യം, പൊതുസേവനം, സാമൂഹിക അംഗീകാരം എളുപ്പത്തിൽ ലഭിക്കും.',
    'Hasta': 'അത്തം നക്ഷത്രത്തിൽ ജനിച്ച നിങ്ങൾ കൈത്തൊഴിൽ വൈദഗ്ധ്യവും ബുദ്ധിസാമർത്ഥ്യവും നർമ്മബോധവും ഉള്ളവരാണ്. കൈപ്പുണ്യമുള്ളവർ. വ്യാപാരം, കണക്ക്, എഴുത്ത്, കലകൾ എന്നിവയിൽ ശോഭിക്കും.',
    'Chitra': 'ചിത്തിര നക്ഷത്രത്തിൽ ജനിച്ച നിങ്ങൾ രത്നം പോലെ തിളങ്ങുന്ന ആകർഷണവും കലാസൂക്ഷ്മതയും വ്യത്യസ്തമായ ചിന്തയും ഉള്ളവരാണ്. വിശ്വകർമ്മാവിന്റെ അംശത്താൽ രൂപകല്പന, എഞ്ചിനീയറിംഗ്, വാസ്തുവിദ്യ എന്നിവയിൽ മുദ്ര പതിപ്പിക്കും.',
    'Swati': 'ചോതി നക്ഷത്രത്തിൽ ജനിച്ച നിങ്ങൾ സ്വതന്ത്രചിന്തയും ഒത്തുതീർപ്പുമനോഭാവവും സത്യസന്ധതയും ഉള്ളവരാണ്. കാറ്റിലാടുന്ന ഇളംനാമ്പ് പോലെ വഴക്കത്തോടെ കാര്യങ്ങൾ നേടും. വ്യാപാരം, നിയമം, വിദേശബന്ധങ്ങൾ എന്നിവയിൽ ഉന്നതി നേടും.',
    'Vishakha': 'വിശാഖം നക്ഷത്രത്തിൽ ജനിച്ച നിങ്ങൾ ദൃഢനിശ്ചയവും കഠിനാധ്വാനവും ലക്ഷ്യം നേടാനുള്ള തീവ്രതയും ഉള്ളവരാണ്. വിജയകമാനം പോലെ ഏതു രംഗത്തും മുന്നിൽ നിൽക്കും. നേതൃചുമതലകളും നേട്ടങ്ങളും നിങ്ങളെ തേടിയെത്തും.',
    'Anuradha': 'അനിഴം നക്ഷത്രത്തിൽ ജനിച്ച നിങ്ങൾ സൗഹൃദമനസ്സും ഭക്തിയും കഠിനാധ്വാനവും ഉള്ളവരാണ്. സൗഹൃദങ്ങളും സംഘടനകളും വഴി ഉയർച്ച നേടും. വിദേശയാത്രകളും വിദേശത്ത് നേട്ടങ്ങളും ഉണ്ടാകും. ക്ഷമയോടെ മുന്നേറിയാൽ സ്ഥിരമായ വിജയം.',
    'Jyeshtha': 'തൃക്കേട്ട നക്ഷത്രത്തിൽ ജനിച്ച നിങ്ങൾ ആത്മാഭിമാനവും നേതൃശേഷിയും സംരക്ഷണബോധവും ഉള്ളവരാണ്. മൂത്തവരുടെ ഉത്തരവാദിത്തം ഏറ്റെടുക്കുന്ന പ്രകൃതം. ഭരണം, പ്രതിരോധം, ഗവേഷണം എന്നിവയിൽ ഉന്നതി. അഹംഭാവം ഒഴിവാക്കിയാൽ എല്ലാവരുടെയും സ്നേഹം നേടും.',
    'Mula': 'മൂലം നക്ഷത്രത്തിൽ ജനിച്ച നിങ്ങൾ കാര്യങ്ങളുടെ വേരുവരെ അന്വേഷിക്കുന്ന ആഴമുള്ള ചിന്തയും ധൈര്യവും ആത്മീയതയും ഉള്ളവരാണ്. പഴയതിനെ മാറ്റി പുതിയത് സൃഷ്ടിക്കാനുള്ള ശേഷിയുണ്ട്. ഗവേഷണം, വൈദ്യം, തത്ത്വചിന്ത എന്നിവയിൽ മികവ് പുലർത്തും.',
    'Purva Ashadha': 'പൂരാടം നക്ഷത്രത്തിൽ ജനിച്ച നിങ്ങൾ അജയ്യമായ ആത്മവിശ്വാസവും വാക്ചാതുര്യവും കലാഭിരുചിയും ഉള്ളവരാണ്. ജലം പോലെ എല്ലാ തടസ്സങ്ങളെയും മറികടന്ന് മുന്നേറും. പ്രഭാഷണം, കല, നിയമം, വ്യാപാരം എന്നിവയിൽ വിജയം.',
    'Uttara Ashadha': 'ഉത്രാടം നക്ഷത്രത്തിൽ ജനിച്ച നിങ്ങൾ സത്യസന്ധതയും കർത്തവ്യബോധവും ദീർഘവീക്ഷണവും ഉള്ളവരാണ്. തുടങ്ങിയ കാര്യം പൂർത്തിയാക്കുന്ന സ്ഥിരതയുണ്ട്. ഭരണം, സർക്കാർ, സാമൂഹിക നേതൃത്വം എന്നിവയിൽ ശാശ്വതമായ വിജയം നേടും.',
    'Shravana': 'തിരുവോണം നക്ഷത്രത്തിൽ ജനിച്ച നിങ്ങൾ ശ്രദ്ധയോടെ കേൾക്കാനും പഠിക്കാനുമുള്ള കഴിവും വിനയവും ഭക്തിയും ഉള്ളവരാണ്. വിഷ്ണുവിന്റെ അനുഗ്രഹത്താൽ വിദ്യ, അധ്യാപനം, മാധ്യമം, ഉപദേശം എന്നിവയിൽ പ്രശസ്തി നേടും. ജനങ്ങളുടെ വിശ്വാസം എളുപ്പത്തിൽ നേടും.',
    'Dhanishtha': 'അവിട്ടം നക്ഷത്രത്തിൽ ജനിച്ച നിങ്ങൾ താളബോധവും സമ്പത്തും സംഗീതാഭിരുചിയും സംഘടനാശേഷിയും ഉള്ളവരാണ്. ചൊവ്വയുടെ സ്വാധീനത്താൽ ധൈര്യവും പ്രവർത്തനശേഷിയുമുണ്ട്. സമ്പത്തിന്റെയും വിഭവങ്ങളുടെയും മികച്ച കൈകാര്യം നിങ്ങളുടെ ശക്തിയാണ്.',
    'Shatabhisha': 'ചതയം നക്ഷത്രത്തിൽ ജനിച്ച നിങ്ങൾ രഹസ്യങ്ങൾ അറിയാനുള്ള ജിജ്ഞാസയും രോഗശാന്തി നൽകാനുള്ള കഴിവും സ്വതന്ത്രചിന്തയും ഉള്ളവരാണ്. നൂറ് വൈദ്യന്മാരുടെ നക്ഷത്രം എന്ന പേര് പോലെ വൈദ്യം, ശാസ്ത്രം, സാങ്കേതികവിദ്യ എന്നിവയിൽ തിളങ്ങും.',
    'Purva Bhadrapada': 'പൂരുരുട്ടാതി നക്ഷത്രത്തിൽ ജനിച്ച നിങ്ങൾ ആദർശനിഷ്ഠയും തീവ്രമായ ചിന്തയും ആത്മീയ ഔന്നത്യവും ഉള്ളവരാണ്. ധനകാര്യം, തത്ത്വചിന്ത, സാമൂഹിക പരിഷ്കരണം എന്നിവയിൽ മുന്നിൽ നിൽക്കും. അതിരുകടന്ന നിലപാടുകൾ ഒഴിവാക്കി സമനില പാലിക്കുക.',
    'Uttara Bhadrapada': 'ഉത്രട്ടാതി നക്ഷത്രത്തിൽ ജനിച്ച നിങ്ങൾ ആഴമുള്ള അറിവും ക്ഷമയും കരുണയും ഉള്ളവരാണ്. ശനിയുടെ സ്വാധീനത്താൽ അച്ചടക്കത്തോടെ സ്ഥിരമായ ഉയർച്ച നേടും. ആത്മീയത, ദാനധർമ്മം, ഗവേഷണം എന്നിവയിൽ താൽപ്പര്യമുണ്ട്. കുടുംബത്തിന് താങ്ങും തണലുമാകും.',
    'Revati': 'രേവതി നക്ഷത്രത്തിൽ ജനിച്ച നിങ്ങൾ കരുണയും സൗമ്യതയും കലാഭിരുചിയും ഉള്ളവരാണ്. ബുധന്റെ അനുഗ്രഹത്താൽ ബുദ്ധിസാമർത്ഥ്യവും ആശയവിനിമയശേഷിയുമുണ്ട്. യാത്ര, കല, സേവനം, ആത്മീയത എന്നിവയിൽ സംതൃപ്തി കണ്ടെത്തും. എല്ലാവരെയും സംരക്ഷിക്കുന്ന നല്ല മനസ്സുണ്ട്.',
}

LAGNA_ML = {
    'Aries': 'മേട ലഗ്നത്തിൽ ജനിച്ച നിങ്ങൾക്ക് ചൊവ്വയുടെ സ്വാധീനത്താൽ ചുറുചുറുക്കുള്ള ശരീരവും തിളക്കമുള്ള മുഖവും ആത്മവിശ്വാസവും ഉണ്ട്. വേഗതയുള്ള നടത്തം, നേരിട്ടുള്ള സംസാരം, മറ്റുള്ളവരെ നയിക്കാനുള്ള കഴിവ് എന്നിവയുണ്ട്. എന്തിലും മുന്നിൽ നിൽക്കാൻ ആഗ്രഹിക്കും.',
    'Taurus': 'ഇടവ ലഗ്നത്തിൽ ജനിച്ച നിങ്ങൾക്ക് ശുക്രന്റെ അനുഗ്രഹത്താൽ ആകർഷകമായ രൂപവും ഉറച്ച ശരീരവും മധുരമായ ശബ്ദവും ഉണ്ട്. ക്ഷമയും സമചിത്തതയുമാണ് ശക്തി. കലാഭിരുചി, ഭൂമി, വസ്ത്രാഭരണ ശേഖരം എന്നിവ നന്നായി ലഭിക്കും.',
    'Gemini': 'മിഥുന ലഗ്നത്തിൽ ജനിച്ച നിങ്ങൾക്ക് ബുധന്റെ സ്വാധീനത്താൽ യൗവനം തോന്നുന്ന രൂപവും ആകർഷകമായ നോട്ടവും ബഹുമുഖ കഴിവുകളും ഉണ്ട്. നർമ്മബോധം, പ്രസംഗശേഷി, എഴുത്തുകഴിവ് എന്നിവയുണ്ട്. വ്യാപാരത്തിലും ആശയവിനിമയത്തിലും ശോഭിക്കും.',
    'Cancer': 'കർക്കടക ലഗ്നത്തിൽ ജനിച്ച നിങ്ങൾക്ക് ചന്ദ്രന്റെ അംശത്താൽ ശാന്തമായ മുഖവും കരുണയുള്ള മനസ്സും ആഴമുള്ള സ്നേഹവും ഉണ്ട്. മാതൃസ്നേഹവും കുടുംബബന്ധവും കൂടുതൽ. ഭാവനയും ഉൾക്കാഴ്ചയും നിങ്ങളെ നയിക്കും.',
    'Leo': 'ചിങ്ങ ലഗ്നത്തിൽ ജനിച്ച നിങ്ങൾക്ക് സൂര്യന്റെ സ്വാധീനത്താൽ ഗാംഭീര്യമുള്ള നടത്തവും സിംഹം പോലെയുള്ള ഉദാരതയും നേതൃഗുണവും ഉണ്ട്. അനീതി കണ്ടാൽ പ്രതികരിക്കും. സമൂഹത്തിൽ ഉയർന്ന പദവിയും ആദരവും നേടും.',
    'Virgo': 'കന്നി ലഗ്നത്തിൽ ജനിച്ച നിങ്ങൾക്ക് ബുധന്റെ അനുഗ്രഹത്താൽ ശാന്തമായ രൂപവും മൂർച്ചയുള്ള ബുദ്ധിയും സൂക്ഷ്മമായ പ്രവർത്തനരീതിയും ഉണ്ട്. എന്തും ആസൂത്രണം ചെയ്ത് ഭംഗിയായി ചെയ്യും. കണക്ക്, ഭരണം, വൈദ്യം എന്നിവയിൽ മികവ് കാണിക്കും.',
    'Libra': 'തുലാം ലഗ്നത്തിൽ ജനിച്ച നിങ്ങൾക്ക് ശുക്രന്റെ സ്വാധീനത്താൽ സുന്ദരമായ രൂപവും ആകർഷകമായ ചിരിയും നിഷ്പക്ഷമായ ചിന്തയും ഉണ്ട്. ത്രാസ് പോലെ നീതിബോധമുണ്ട്; നിയമം, വ്യാപാരം, പൊതുജീവിതം എന്നിവയിൽ സൽപ്പേര് നേടും.',
    'Scorpio': 'വൃശ്ചിക ലഗ്നത്തിൽ ജനിച്ച നിങ്ങൾക്ക് ചൊവ്വയുടെ സ്വാധീനത്താൽ തുളച്ചുകയറുന്ന കാന്തിക കണ്ണുകളും ആഴമുള്ള മനോബലവും ഉണ്ട്. ഏതു രഹസ്യവും മനസ്സിലാക്കും. പരീക്ഷണങ്ങളെ നേട്ടങ്ങളാക്കി മാറ്റാനുള്ള അസാധാരണ ശക്തിയുണ്ട്.',
    'Sagittarius': 'ധനു ലഗ്നത്തിൽ ജനിച്ച നിങ്ങൾക്ക് വ്യാഴത്തിന്റെ അനുഗ്രഹത്താൽ ഉയരമുള്ള രൂപവും വിശാലമായ നെറ്റിയും ആത്മീയ ജ്ഞാനവും ഉണ്ട്. വില്ലിലെ അമ്പ് പോലെയുള്ള നേർവഴിയും ധർമ്മചിന്തയും തത്ത്വചിന്താതാൽപ്പര്യവും നിങ്ങളെ ഉയർത്തും.',
    'Capricorn': 'മകര ലഗ്നത്തിൽ ജനിച്ച നിങ്ങൾക്ക് ശനിയുടെ സ്വാധീനത്താൽ ഉറച്ച ശരീരവും കഠിനാധ്വാനവും കർത്തവ്യബോധവും ഉണ്ട്. ചെറുപ്പത്തിൽ പോരാട്ടങ്ങൾ ഉണ്ടായാലും പടിപടിയായി മുന്നേറി പ്രായമാകുമ്പോൾ ഉന്നതിയിലെത്തും.',
    'Aquarius': 'കുംഭ ലഗ്നത്തിൽ ജനിച്ച നിങ്ങൾക്ക് ശനിയുടെ സ്വാധീനത്താൽ വിശാലമായ മനസ്സും ശാസ്ത്രീയ ചിന്തയും പൊതുനന്മയോടുള്ള താൽപ്പര്യവും ഉണ്ട്. കുടം പോലെ ജ്ഞാനത്തിന്റെ നിധി. പുതിയ കണ്ടുപിടുത്തങ്ങളിലും സാമൂഹിക മാറ്റങ്ങളിലും മുന്നിൽ നിൽക്കും.',
    'Pisces': 'മീന ലഗ്നത്തിൽ ജനിച്ച നിങ്ങൾക്ക് വ്യാഴത്തിന്റെ അനുഗ്രഹത്താൽ കരുണ നിറഞ്ഞ കണ്ണുകളും മൃദുവായ ഹൃദയവും ദൈവഭക്തിയും ഉണ്ട്. കല, സംഗീതം, ധ്യാനം, ആത്മീയത എന്നിവയിൽ താൽപ്പര്യവും മറ്റുള്ളവരുടെ ദുഃഖം തീർക്കാനുള്ള നല്ല മനസ്സുമുണ്ട്.',
}
